#!/usr/bin/env python3
"""Read-only campaign closeout, scoped to the delivered IDs and saved preimages."""
import importlib.util, json
from datetime import datetime, timezone
from pathlib import Path
sp=importlib.util.spec_from_file_location('campaign',Path(__file__).with_name('creators-deep-4h-20261010.py'))
x=importlib.util.module_from_spec(sp);sp.loader.exec_module(x)
assert datetime.now(timezone.utc)>=datetime.fromisoformat(x.DEADLINE.replace('Z','+00:00'))
out=[]
for p in sorted((x.BASE/'creators').glob('*/creator-verified.json')):
 x.configure(p.parent.name);proof=x.r.load(p);plan=x.r.load(x.RUN/'image-selection.json.gz');ids=[r['artwork_id'] for r in plan['rows']]
 expected=x.r.load(x.c.BACKUP/'image-postimages.json.gz')['records']
 with x.r.connect('production') as db,db.transaction():
  db.execute('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY')
  current=x.s.snapshots(db,ids);assert current==expected,(p.parent.name,'Delivered objects changed')
  if (x.c.BACKUP/'locked-preimages.json.gz').exists():
   before=x.r.load(x.c.BACKUP/'locked-preimages.json.gz');assert x.s.snapshots(db,list(before))==before
   preserved=len(before)
  else:preserved=None
  media=db.execute('SELECT a.id::text,ma.checksum_sha256,ma.byte_size FROM artworks a JOIN media_assets ma ON ma.id=a.primary_media_id WHERE a.id=ANY(%s::uuid[])',(ids,)).fetchall()
  assert len(media)==len(ids) and all(0<v['byte_size']<=100000 for v in media)
 for row in current.values():
  a=row['artwork'];assert a['status']=='review' and a['published_at'] is None
  assert not any(v['claim_type']=='display' for v in row['locations'])
 native=x.r.load(x.RUN/'native-research-applied.json') if (x.RUN/'native-research-applied.json').exists() else {}
 out.append(dict(**proof,original_records_preserved=preserved,native_citations=native.get('native_citations',0),holdings_added=native.get('holdings_added',0),final_database_snapshot_matches=True))
summary=dict(at=x.r.now(),start_utc=x.START,research_window_end_utc=x.DEADLINE,delivery_closeout_utc=x.r.now(),completed_creators=out,new_artworks=sum(v['added_this_campaign'] for v in out),new_images=sum(v['images_added_this_campaign'] for v in out),native_citations=sum(v['native_citations'] for v in out),holdings_added=sum(v['holdings_added'] for v in out),current_display_claims=0,local_database_connected=False,goal_complete=True)
x.r.save(x.BASE/'final-audit.json',summary)
progress=x.r.load(x.BASE/'progress.json');progress.update(goal_complete=True,completed_at=x.r.now(),final_audit='final-audit.json');(x.BASE/'progress.json').write_text(json.dumps(progress,ensure_ascii=False,indent=2))
lines=['# Four-hour creator research and delivery — 10 October 2026','',f"Research window: {x.START}–{x.DEADLINE}. Final delivery verification: {summary['at']}. The last reviewed Buchet selection was delivered and checked during closeout immediately after the research window.",'',f"Production result: **{summary['new_artworks']} new artworks and {summary['new_images']} authentic images**, including ten supplementary images on previously added Tvorozhnikov records. Five creators received 11–23 new works each. New works remain in review and are visible in the unified catalogue. No publication, current-display claims, local database connection, commit or deployment was performed.",'','| Creator | Linked works at selection | New artworks | Images added | Linked total verified |','| --- | ---: | ---: | ---: | ---: |']
for v in out:
 lines.append(f"| {v['artist']} | {v['initial_count']} | {v['added_this_campaign']} | {v['images_added_this_campaign']} | {v['active_total']} |")
lines += ['', 'The initial counts above are linked active works. Additional raw-label and alternate-profile records were searched and compared before adding objects. These comparison records are not included in the linked totals. Existing linked and raw-label objects were preserved; ambiguous duplicate profiles were held rather than merged.', '',f"The additions carry {summary['native_citations']} supplementary research citations and {summary['holdings_added']} documented museum links. Collection credits remain distinct from current display. WikiArt image rights labels remain separate from the user’s source approval.",'', '## Object-level decisions','', '- Streeton: 16 additions; museum catalogues and the 2020 AGNSW exhibition labels distinguish repeated landscape titles, sketches, later acquisitions and private collection credits. Existing Templestowe and Sirius Cove variants were compared and excluded where appropriate.', '- Holbein the Elder: 19 additions; individual Grey Passion and Saint Sebastian panels were distinguished from ensemble photographs, alternate faces, details and duplicates. Historic loans are not treated as ownership transfers.', '- Clarke: 23 distinct full-page illustrations matched to the 1920 primary edition of The Year’s at the Spring. The publication year does not invent an original drawing execution date, and a museum library copy does not establish ownership of an original drawing.', '- Kondzelevych: 11 icons; four creator links remain attributed-to. Museum publications resolve individual panels, inventories, inscriptions and provenance; seven numeric dates remain unknown. The Bobly mounted Saint George is distinguished from the standing Okorsk saint. Lviv National Art Gallery is not substituted for the National Museum in Lviv.', '- Buchet: 15 works; nine exact primary museum/auction matches. Two double-sided canvases are represented once each with the selected face stated. Two Frauenakt compositions with identical titles/dates remain distinct. Framed and image-opening measurements are not imported as object measurements. Two MCBA acquisitions have verified accession numbers.', '- Tvorozhnikov: ten images supplement the preceding 25-work metadata pass; those earlier metadata additions are excluded from this campaign’s new-artwork total.', '', '## Holds and limitations','', '- Nikitin: duplicate creator profiles and a possible icon-painter homonym; no new records.', '- Russell: extra raw-label works exceed the intended small-collection target; a suspected British/Australian creator conflict and source login redirect remain unresolved.', '- Ushakov: two linked plus five raw-label objects; no additional records. Repeated faces and details excluded.', '- Ghikas: duplicate Nicolas Ghika profile already contains thirteen works; no additions. Bauernfeind already has twenty linked works.', '- Unknown dates, uncertain attributions, unverified auction leads and unselected works remain documented in each frozen reviewed plan. The pass is selective, not an exhaustive catalogue raisonné.', '- Denied source endpoints, TLS failures and the unusable black comparison image were retained as research limitations and not bypassed. All delivered images are authentic selected WikiArt reproductions; full supplied frames were preserved.', '', '## Evidence and verification','', '- `final-audit.json`: fresh production snapshots for every delivered image target and preserved pre-existing records.', '- `progress.json`: per-creator totals and completion time.', '- `creators/*/reviewed-plan.json.gz`: immutable metadata selection, exclusions, object decisions, source receipts and checksums.', '- `creators/*/visual-review.json`, `images-verified.json`, `creator-verified.json`: visual decisions, live image byte verification and bounded public API verification.', '- Source registry: `source-registry-review.json`; source captures remain with each creator. Original images, PDF research documents and transaction backups are kept under the designated Artline Library directories.', '', 'All 94 image deliveries passed full-frame visual review, the 100,000-byte limit, source identity checks, database attachment checks and public SHA-256 checks. A transient Buchet verification timeout was retried without repeating mutations. Production mutations used the shared advisory lock, create-only asset upload and saved transaction preimages.', '']
(x.BASE/'README.md').write_text('\n'.join(lines))
print(json.dumps({k:v for k,v in summary.items() if k!='completed_creators'}))
